// KNN-7 Neighbour Vote 3D
// K-nearest-neighbour vote on next-bar direction: vote margin + disagreement channels

k = input(7, "K Neighbors", 1, 15, 1)
featureBars = input(20, "Feature Bars", 5, 40, 1)
minHistory = input(100, "Min History", 30, 300, 5)
marginThreshold = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
disagreeThreshold = input(0.35, "Disagree Threshold", 0.05, 0.9, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Per-bar return ────────────────────────────────────────
prevC = close[1]
rRaw = 0.0
if bar_index > 0 {
    rRaw := (close - prevC) / (prevC + 0.0000001)
}
rCur = rRaw

// ─── Persistent history ────────────────────────────────────
var retHist = array(0)
var closeHist = array(0)

array.push(retHist, rCur)
array.push(closeHist, close)

// ─── KNN vote ──────────────────────────────────────────────
nBars = array.size(retHist)

upCount = 0
downCount = 0
margin = 0.0
disagree = 0.0
meanD = 0.0
spreadN = 0.0

if nBars >= minHistory + featureBars {
    bestD0 = 999999.0
    bestD1 = 999999.0
    bestD2 = 999999.0
    bestD3 = 999999.0
    bestD4 = 999999.0
    bestD5 = 999999.0
    bestD6 = 999999.0
    bestL0 = 0
    bestL1 = 0
    bestL2 = 0
    bestL3 = 0
    bestL4 = 0
    bestL5 = 0
    bestL6 = 0

    curTop = nBars - 1
    j = featureBars
    if nBars - 60 > featureBars { j := nBars - 60 }
    jLast = curTop - 2
    while j <= jLast {
        // Euclidean distance over last featureBars returns
        dd = 0.0
        n = 0
        while n < featureBars {
            a = retHist[curTop - n]
            b = retHist[j - n]
            diff = a - b
            dd := dd + diff * diff
            n := n + 1
        }
        dist = sqrt(dd + 0.000000001)

        // label of j by realized next-bar direction
        cj = closeHist[j]
        cnx = closeHist[j + 1]
        lab = -1
        if cnx > cj { lab := 1 }

        // insert into sorted top-k (k fixed 7 per design)
        if dist < bestD0 {
            bestD6 := bestD5
            bestL6 := bestL5
            bestD5 := bestD4
            bestL5 := bestL4
            bestD4 := bestD3
            bestL4 := bestL3
            bestD3 := bestD2
            bestL3 := bestL2
            bestD2 := bestD1
            bestL2 := bestL1
            bestD1 := bestD0
            bestL1 := bestL0
            bestD0 := dist
            bestL0 := lab
        } else {
            if dist < bestD1 {
                bestD6 := bestD5
                bestL6 := bestL5
                bestD5 := bestD4
                bestL5 := bestL4
                bestD4 := bestD3
                bestL4 := bestL3
                bestD3 := bestD2
                bestL3 := bestL2
                bestD2 := bestD1
                bestL2 := bestL1
                bestD1 := dist
                bestL1 := lab
            } else {
                if dist < bestD2 {
                    bestD6 := bestD5
                    bestL6 := bestL5
                    bestD5 := bestD4
                    bestL5 := bestL4
                    bestD4 := bestD3
                    bestL4 := bestL3
                    bestD3 := bestD2
                    bestL3 := bestL2
                    bestD2 := dist
                    bestL2 := lab
                } else {
                    if dist < bestD3 {
                        bestD6 := bestD5
                        bestL6 := bestL5
                        bestD5 := bestD4
                        bestL5 := bestL4
                        bestD4 := bestD3
                        bestL4 := bestL3
                        bestD3 := dist
                        bestL3 := lab
                    } else {
                        if dist < bestD4 {
                            bestD6 := bestD5
                            bestL6 := bestL5
                            bestD5 := bestD4
                            bestL5 := bestL4
                            bestD4 := dist
                            bestL4 := lab
                        } else {
                            if dist < bestD5 {
                                bestD6 := bestD5
                                bestL6 := bestL5
                                bestD5 := dist
                                bestL5 := lab
                            } else {
                                if dist < bestD6 {
                                    bestD6 := dist
                                    bestL6 := lab
                                }
                            }
                        }
                    }
                }
            }
        }
        j := j + 1
    }

    // count votes from filled neighbour slots
    u = 0
    d = 0
    if bestD0 < 999998.0 {
        if bestL0 == 1 { u := u + 1 } else { d := d + 1 }
    }
    if bestD1 < 999998.0 {
        if bestL1 == 1 { u := u + 1 } else { d := d + 1 }
    }
    if bestD2 < 999998.0 {
        if bestL2 == 1 { u := u + 1 } else { d := d + 1 }
    }
    if bestD3 < 999998.0 {
        if bestL3 == 1 { u := u + 1 } else { d := d + 1 }
    }
    if bestD4 < 999998.0 {
        if bestL4 == 1 { u := u + 1 } else { d := d + 1 }
    }
    if bestD5 < 999998.0 {
        if bestL5 == 1 { u := u + 1 } else { d := d + 1 }
    }
    if bestD6 < 999998.0 {
        if bestL6 == 1 { u := u + 1 } else { d := d + 1 }
    }
    upCount := u
    downCount := d

    tot = u + d
    m = 0.0
    if tot > 0 { m := (u - d) / tot }
    margin := m

    // neighbour distance spread: stdev / mean over filled slots
    cnt = tot + 0.0
    md = 0.0
    if tot > 0 { md := (bestD0 + bestD1 + bestD2 + bestD3 + bestD4 + bestD5 + bestD6) / cnt }
    // slots beyond tot hold 999999 — recompute mean from filled only
    md2 = 0.0
    if bestD0 < 999998.0 { md2 := md2 + bestD0 }
    if bestD1 < 999998.0 { md2 := md2 + bestD1 }
    if bestD2 < 999998.0 { md2 := md2 + bestD2 }
    if bestD3 < 999998.0 { md2 := md2 + bestD3 }
    if bestD4 < 999998.0 { md2 := md2 + bestD4 }
    if bestD5 < 999998.0 { md2 := md2 + bestD5 }
    if bestD6 < 999998.0 { md2 := md2 + bestD6 }
    if tot > 0 { md2 := md2 / cnt }
    meanD := md2

    vv = 0.0
    if bestD0 < 999998.0 { vv := vv + (bestD0 - md2) * (bestD0 - md2) }
    if bestD1 < 999998.0 { vv := vv + (bestD1 - md2) * (bestD1 - md2) }
    if bestD2 < 999998.0 { vv := vv + (bestD2 - md2) * (bestD2 - md2) }
    if bestD3 < 999998.0 { vv := vv + (bestD3 - md2) * (bestD3 - md2) }
    if bestD4 < 999998.0 { vv := vv + (bestD4 - md2) * (bestD4 - md2) }
    if bestD5 < 999998.0 { vv := vv + (bestD5 - md2) * (bestD5 - md2) }
    if bestD6 < 999998.0 { vv := vv + (bestD6 - md2) * (bestD6 - md2) }
    sd = 0.0
    if tot > 0 { sd := sqrt(vv / cnt) }
    cv = sd / (md2 + 0.0000001)
    spN = cv / (1.0 + cv)
    spreadN := spN
    disagree := 0.6 * (1.0 - abs(m)) + 0.4 * spN
}

// ─── Signal conditions (both channels must agree) ───────────
ready = bar_index >= minHistory + featureBars
buyCond = ready and margin > marginThreshold and disagree < disagreeThreshold
sellCond = ready and margin < 0 - marginThreshold and disagree < disagreeThreshold
buySig = buyCond and not buyCond[1]
sellSig = sellCond and not sellCond[1]

// ─── 2D markers ────────────────────────────────────────────
if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }

// ─── 2D channels (independently readable) ──────────────────
plot(margin, "Vote Margin", "#b48cff", 2, "separate")
plot(disagree, "Disagreement", "#ffd43b", 2, "separate")
hline(marginThreshold, "#22cc88", "separate")
hline(0 - marginThreshold, "#ff4477", "separate")
hline(disagreeThreshold, "#ffd43b", "separate")
hline(0, "rgba(180,140,255,0.5)", "separate")

// ─── 3D form: crisp = tall narrow spike, contested = short wide slab ──
// (A) pillar height = vote margin as extruded columns
plot3d(margin, "Margin Pillars", "bars3d", "#b48cff", "separate", 0)
// (B) pillar footprint = disagreement as second column channel
plot3d(disagree, "Disagree Pillars", "bars3d", "#ffd43b", "separate", 1)

if buySig { plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate") }
if sellSig { plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "separate") }

// Visible Session Volume Value Signal Analysis Model
// Session volume profile: POC + value area, breakout signals, 2D + 3D parity.

rows = input(24, "Rows", 10, 40, 1)
vaPct = input(70, "Value Area %", 50, 90, 5)
sessLen = input(120, "Session Length", 20, 500, 10)
showZone = input(true, "Show Value Zone")
show3D = input(true, "Show 3D")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range ───────────────────────────────────────────────
hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
binH = rng / rows
if binH <= 0 {
    binH := close * 0.001
}

// ─── Row volumes: distribute each session bar's volume pro-rata ──
rowVol = array()
k = 0
while k < rows {
    array.push(rowVol, 0.0)
    k := k + 1
}

j = 0
while j < sessLen {
    hj = high[j]
    lj = low[j]
    vj = volume[j]
    br = hj - lj
    if br <= 0 {
        ci = floor((close[j] - ll) / rng * rows)
        if ci < 0 { ci := 0 }
        if ci > rows - 1 { ci := rows - 1 }
        array.set(rowVol, ci, array.get(rowVol, ci) + vj)
    } else {
        r = 0
        while r < rows {
            rLow = ll + r * binH
            rHigh = rLow + binH
            top = hj
            if rHigh < top { top := rHigh }
            bot = lj
            if rLow > bot { bot := rLow }
            ov = top - bot
            if ov > 0 {
                array.set(rowVol, r, array.get(rowVol, r) + vj * ov / br)
            }
            r := r + 1
        }
    }
    j := j + 1
}

// ─── POC: row with max volume ────────────────────────────────────
pocBin = 0
pocVal = array.get(rowVol, 0)
q = 1
while q < rows {
    v = array.get(rowVol, q)
    if v > pocVal {
        pocVal := v
        pocBin := q
    }
    q := q + 1
}
totalVol = array.sum(rowVol)
pocShare = 0.0
if totalVol > 0 { pocShare := pocVal / totalVol }
pocPrice = ll + (pocBin + 0.5) / rows * rng

// ─── Value area: sort rows by volume desc, accumulate to vaPct ───
visited = array()
m = 0
while m < rows {
    array.push(visited, 0.0)
    m := m + 1
}
target = totalVol * vaPct / 100
accum = 0.0
vaLowBin = pocBin
vaHighBin = pocBin
picked = 0
while accum < target and picked < rows {
    best = 0 - 1
    bestV = 0 - 1.0
    s = 0
    while s < rows {
        if array.get(visited, s) == 0.0 {
            sv = array.get(rowVol, s)
            if sv > bestV {
                bestV := sv
                best := s
            }
        }
        s := s + 1
    }
    if best < 0 { picked := rows }
    if best >= 0 {
        array.set(visited, best, 1.0)
        accum := accum + bestV
        if best < vaLowBin { vaLowBin := best }
        if best > vaHighBin { vaHighBin := best }
        picked := picked + 1
    }
}
vah = ll + (vaHighBin + 1) / rows * rng
val = ll + vaLowBin / rows * rng
vaWidth = vah - val
valueCenter = (vah + val + pocPrice) / 3
terrainPrice = valueCenter + (close - valueCenter) * (0.3 + pocShare * 0.7)

// ─── Position state ──────────────────────────────────────────────
insideVA = close >= val and close <= vah
aboveVA = close > vah
belowVA = close < val

// ─── Signals: price leaving value + POC reclaim ──────────────────
vahPrev = vah[1]
valPrev = val[1]
pocPrev = pocPrice[1]
prevClose = close[1]
buySig = prevClose <= vahPrev and close > vah
sellSig = prevClose >= valPrev and close < val
outsidePrev = prevClose > vahPrev or prevClose < valPrev
crossPocUp = prevClose <= pocPrev and close > pocPrice
crossPocDown = prevClose >= pocPrev and close < pocPrice
reclaimSig = outsidePrev and (crossPocUp or crossPocDown)

// ─── Signal markers (2D + 3D cones, same pane) ───────────────────
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if reclaimSig {
    plotshape(bar_index, close, "POC Reclaim", "circle", "#ffd43b")
}
if show3D {
    if buySig {
        plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "3d")
    }
    if sellSig {
        plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
    }
    if reclaimSig {
        plotshape_3d(bar_index, close, "Reclaim", "diamond", "#ffd43b", 0.8 * markerSize, 0, "3d")
    }
}

// ─── POC rail label (new POC only, no towers) ────────────────────
var lastPocBin = -1.0
if show3D {
    if pocBin != lastPocBin {
        label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 0, "3d")
    }
}
lastPocBin := pocBin

// ─── Value zone shade (moving box, updated in place) ─────────────
if showZone {
    box.new(bar_index - sessLen, vah, bar_index, val, "#22cc8855", "rgba(34,204,136,0.08)", 1, "VAZONE")
}

// ─── 2D: same information when 3D is off ──────────────────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vah, "VAH", "#22cc88", 1, "stepline")
plot(val, "VAL", "#ff4477", 1, "stepline")
plot(terrainPrice, "Value Center", "#4488ff", 1)
plot(pocShare * 100, "POC Share %", "#ffd43b", 1, "separate")

// ─── 3D: value terrain + POC rail + value edge rails ─────────────
if show3D {
    plot3d(terrainPrice, "Value Terrain", "surface", "#4488ff", "3d", 3)
    plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 0)
    plot3d(vah, "VAH Rail", "line3d", "#22cc88", "3d", 1)
}
if insideVA {
    bgcolor("rgba(34,204,136,0.05)")
}

// FIX 1: var lvl = highest(high, 20) froze at bar 0 — var initializers run once, so breakout level never updated.
// FIX 2: close[-1] is a future leak (reads next bar) — corrected to close so the breakout uses the current bar only.
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine syntax — corrected to Oak positional plotshape(bar_index, price, title, style, color).
// FIX 4: plot3d(r, "RSI", "surface", "#b48cff", "3d") forces an oscillator into the price scene — corrected to pane "separate".
